def do_enable(self, arg):
        """enable bpnumber [bpnumber ...]
        Enables the breakpoints given as a space separated list of
        breakpoint numbers.
        """
        if not arg:
            print("No breakpoint number specified.")
            return
        for bp_num in arg.split():
            try:
                bp_num = int(bp_num)
            except ValueError:
                print("Invalid breakpoint number: %s" % bp_num)
                continue
            if bp_num in self.bp_list:
                self.bp_list[bp_num].enable()
            else:
                print("No breakpoint number %s." % bp_num)

